[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>GlobalStone — Global Commercial Real Estate Services</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Playfair+Display:wght@500;600;700&display=swap" rel="stylesheet" />
  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/remixicon/4.2.0/remixicon.min.css" />
  <link rel="stylesheet" href="shared.css" />
  <style>
    /* ── Hero ── */
    .hero {
      position: relative;
      height: 90vh;
      min-height: 600px;
      background: linear-gradient(135deg, #003F2D 0%, #012A2D 60%, #001a1a 100%);
      display: flex;
      align-items: flex-end;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url('https://images.unsplash.com/photo-1486325212027-8081e485255e?w=1600&q=80') center/cover no-repeat;
      opacity: 0.18;
      z-index: 0;
    }
    .hero-grid {
      position: absolute;
      inset: 0;
      background-image: linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
      background-size: 60px 60px;
      z-index: 1;
    }
    .hero-content {
      position: relative;
      z-index: 2;
      padding: 0 0 80px;
      width: 100%;
    }
    .hero-tag {
      display: inline-block;
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      color: #7ECBAF;
      border: 1px solid rgba(126,203,175,0.4);
      padding: 4px 12px;
      border-radius: 2px;
      margin-bottom: 20px;
    }
    .hero h1 {
      font-family: 'Playfair Display', serif;
      font-size: clamp(2.4rem, 5vw, 4rem);
      font-weight: 600;
      color: #fff;
      max-width: 720px;
      line-height: 1.15;
      margin-bottom: 24px;
    }
    .hero p {
      color: rgba(255,255,255,0.72);
      font-size: 1.05rem;
      max-width: 520px;
      line-height: 1.7;
      margin-bottom: 36px;
    }
    .hero-scroll {
      position: absolute;
      bottom: 32px;
      right: var(--container-pad);
      z-index: 2;
      display: flex;
      align-items: center;
      gap: 10px;
      color: rgba(255,255,255,0.5);
      font-size: 12px;
      letter-spacing: 0.08em;
    }
    .hero-scroll::before {
      content: '';
      width: 40px;
      height: 1px;
      background: rgba(255,255,255,0.3);
    }

    /* ── Featured Insights ── */
    .featured-insights {
      background: #fff;
      border-bottom: 1px solid #e5e7eb;
    }
    .insights-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 0;
    }
    .insight-card {
      padding: 36px 32px;
      border-right: 1px solid #e5e7eb;
      transition: background 0.2s;
      cursor: pointer;
      text-decoration: none;
      display: block;
    }
    .insight-card:last-child { border-right: none; }
    .insight-card:hover { background: #f9fafb; }
    .insight-tag {
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: #003F2D;
      margin-bottom: 10px;
    }
    .insight-card h3 {
      font-size: 1rem;
      font-weight: 600;
      color: #111827;
      line-height: 1.5;
      margin-bottom: 12px;
    }
    .insight-arrow {
      color: #003F2D;
      font-size: 18px;
    }

    /* ── Announcement Banner ── */
    .announcement {
      background: #003F2D;
      padding: 18px 0;
    }
    .announcement-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
    }
    .announcement p {
      color: rgba(255,255,255,0.88);
      font-size: 0.95rem;
      font-weight: 500;
    }
    .announcement .btn-ghost-light {
      white-space: nowrap;
      font-size: 13px;
      border: 1px solid rgba(255,255,255,0.35);
      color: #fff;
      padding: 8px 20px;
      border-radius: 2px;
      text-decoration: none;
      transition: background 0.2s, border-color 0.2s;
    }
    .announcement .btn-ghost-light:hover { background: rgba(255,255,255,0.1); border-color: rgba(255,255,255,0.6); }

    /* ── About Statement ── */
    .about-statement {
      background: #f8f9fa;
      padding: 100px 0;
    }
    .about-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .about-label {
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: #003F2D;
      margin-bottom: 20px;
    }
    .about-inner h2 {
      font-family: 'Playfair Display', serif;
      font-size: clamp(1.8rem, 3vw, 2.6rem);
      font-weight: 600;
      color: #111827;
      line-height: 1.3;
    }
    .about-right p {
      color: #4b5563;
      font-size: 1.05rem;
      line-height: 1.85;
      margin-bottom: 32px;
    }
    .stat-row {
      display: flex;
      gap: 40px;
      margin-top: 40px;
    }
    .stat-item {}
    .stat-num {
      font-family: 'Playfair Display', serif;
      font-size: 2.2rem;
      font-weight: 700;
      color: #003F2D;
    }
    .stat-label {
      font-size: 13px;
      color: #6b7280;
      margin-top: 4px;
    }

    /* ── What We Do ── */
    .what-we-do {
      background: #012A2D;
      padding: 100px 0;
    }
    .what-we-do .section-label { color: rgba(255,255,255,0.5); }
    .what-we-do h2 { color: #fff; }
    .tabs-layout {
      display: grid;
      grid-template-columns: 280px 1fr;
      gap: 0;
      margin-top: 56px;
      border: 1px solid rgba(255,255,255,0.08);
    }
    .tab-nav {
      border-right: 1px solid rgba(255,255,255,0.08);
    }
    .tab-btn {
      display: flex;
      align-items: center;
      justify-content: space-between;
      width: 100%;
      padding: 28px 32px;
      background: transparent;
      border: none;
      border-bottom: 1px solid rgba(255,255,255,0.08);
      color: rgba(255,255,255,0.55);
      font-size: 0.95rem;
      font-weight: 500;
      cursor: pointer;
      text-align: left;
      transition: color 0.2s, background 0.2s;
      font-family: 'Inter', sans-serif;
    }
    .tab-btn:last-child { border-bottom: none; }
    .tab-btn.active {
      color: #fff;
      background: rgba(255,255,255,0.04);
    }
    .tab-btn.active::after {
      content: '';
      display: block;
      width: 3px;
      height: 100%;
      background: #7ECBAF;
      position: absolute;
      left: 0;
    }
    .tab-btn:hover { color: #fff; background: rgba(255,255,255,0.03); }
    .tab-btn i { font-size: 16px; opacity: 0.5; }
    .tab-btn.active i { opacity: 1; color: #7ECBAF; }
    .tab-content { display: none; padding: 56px 60px; }
    .tab-content.active { display: block; }
    .tab-content h3 {
      font-family: 'Playfair Display', serif;
      font-size: 1.8rem;
      font-weight: 600;
      color: #fff;
      margin-bottom: 20px;
    }
    .tab-content p {
      color: rgba(255,255,255,0.65);
      font-size: 1.05rem;
      line-height: 1.8;
      max-width: 540px;
      margin-bottom: 32px;
    }

    /* ── Newsletter ── */
    .newsletter {
      background: linear-gradient(135deg, #003F2D, #012A2D);
      padding: 80px 0;
    }
    .newsletter-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 40px;
    }
    .newsletter h2 {
      font-family: 'Playfair Display', serif;
      font-size: 2rem;
      color: #fff;
      margin-bottom: 10px;
    }
    .newsletter p { color: rgba(255,255,255,0.65); font-size: 1rem; }
    .newsletter-form {
      display: flex;
      gap: 0;
      flex-shrink: 0;
    }
    .newsletter-form input {
      padding: 14px 20px;
      font-size: 0.9rem;
      border: 1px solid rgba(255,255,255,0.2);
      background: rgba(255,255,255,0.07);
      color: #fff;
      width: 280px;
      outline: none;
      font-family: 'Inter', sans-serif;
    }
    .newsletter-form input::placeholder { color: rgba(255,255,255,0.4); }
    .newsletter-form input:focus { border-color: rgba(255,255,255,0.4); }
    .newsletter-form button {
      padding: 14px 28px;
      background: #7ECBAF;
      color: #003F2D;
      font-weight: 700;
      font-size: 0.85rem;
      letter-spacing: 0.08em;
      border: none;
      cursor: pointer;
      font-family: 'Inter', sans-serif;
      transition: background 0.2s;
    }
    .newsletter-form button:hover { background: #9DDBC0; }

    /* ── Latest Insights ── */
    .latest-insights { padding: 100px 0; background: #fff; }
    .section-header-row {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 48px;
    }
    .insights-list {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 32px;
    }
    .insight-item {
      border: 1px solid #e5e7eb;
      overflow: hidden;
      transition: box-shadow 0.2s;
    }
    .insight-item:hover { box-shadow: 0 8px 32px rgba(0,0,0,0.08); }
    .insight-img {
      width: 100%;
      height: 200px;
      background: linear-gradient(135deg, #003F2D, #012A2D);
      position: relative;
      overflow: hidden;
    }
    .insight-img img { width: 100%; height: 100%; object-fit: cover; opacity: 0.7; }
    .insight-img-label {
      position: absolute;
      top: 16px;
      left: 16px;
      font-size: 10px;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      background: #7ECBAF;
      color: #003F2D;
      padding: 3px 8px;
    }
    .insight-body { padding: 24px; }
    .insight-body .cat { font-size: 11px; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; color: #003F2D; margin-bottom: 8px; }
    .insight-body h4 { font-size: 1rem; font-weight: 600; color: #111827; line-height: 1.5; margin-bottom: 12px; }
    .insight-body .date { font-size: 12px; color: #9ca3af; }

    /* ── Our Commitment ── */
    .our-commitment { padding: 100px 0; background: #f8f9fa; }
    .commitment-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
      margin-top: 48px;
    }
    .commitment-card {
      background: #fff;
      padding: 36px 28px;
      border-top: 3px solid #003F2D;
      transition: box-shadow 0.2s, transform 0.2s;
    }
    .commitment-card:hover { box-shadow: 0 12px 40px rgba(0,0,0,0.08); transform: translateY(-2px); }
    .commitment-card .icon-wrap {
      width: 44px;
      height: 44px;
      background: rgba(0,63,45,0.08);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
      color: #003F2D;
      font-size: 20px;
    }
    .commitment-card h3 { font-size: 1.05rem; font-weight: 700; color: #111827; margin-bottom: 12px; }
    .commitment-card p { font-size: 0.9rem; color: #6b7280; line-height: 1.7; margin-bottom: 20px; }
    .commitment-card a { font-size: 13px; font-weight: 600; color: #003F2D; text-decoration: none; display: flex; align-items: center; gap: 6px; }
    .commitment-card a:hover { gap: 10px; }

    /* Responsive */
    @media (max-width: 1024px) {
      .insights-grid { grid-template-columns: 1fr; }
      .insight-card { border-right: none; border-bottom: 1px solid #e5e7eb; }
      .insight-card:last-child { border-bottom: none; }
      .about-inner { grid-template-columns: 1fr; gap: 40px; }
      .tabs-layout { grid-template-columns: 1fr; }
      .tab-nav { border-right: none; border-bottom: 1px solid rgba(255,255,255,0.08); display: flex; overflow-x: auto; }
      .tab-btn { border-bottom: none; border-right: 1px solid rgba(255,255,255,0.08); white-space: nowrap; padding: 20px 24px; }
      .tab-content { padding: 36px; }
      .newsletter-inner { flex-direction: column; align-items: flex-start; }
      .newsletter-form { flex-direction: column; width: 100%; }
      .newsletter-form input { width: 100%; }
      .insights-list { grid-template-columns: 1fr; }
      .commitment-grid { grid-template-columns: repeat(2, 1fr); }
    }
    @media (max-width: 640px) {
      .hero h1 { font-size: 2rem; }
      .commitment-grid { grid-template-columns: 1fr; }
      .stat-row { flex-wrap: wrap; gap: 24px; }
      .announcement-inner { flex-direction: column; align-items: flex-start; }
    }
  </style>
</head>
