arguments.content:
/* ── Reset & Base ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 16px;
  color: #111827;
  background: #fff;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { cursor: pointer; font-family: inherit; }

/* ── Variables ── */
:root {
  --green: #003F2D;
  --teal: #012A2D;
  --accent: #7ECBAF;
  --gray-50: #f8f9fa;
  --gray-100: #f3f4f6;
  --gray-200: #e5e7eb;
  --gray-400: #9ca3af;
  --gray-600: #4b5563;
  --gray-700: #374151;
  --gray-900: #111827;
  --container-pad: clamp(20px, 5vw, 80px);
  --container-max: 1280px;
}

/* ── Layout ── */
.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--container-pad);
}

/* ── Typography ── */
.section-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #003F2D;
  margin-bottom: 12px;
}
.section-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  font-weight: 600;
  color: #111827;
  line-height: 1.25;
}

/* ── Buttons ── */
.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #003F2D;
  color: #fff;
  font-weight: 600;
  font-size: 0.875rem;
  letter-spacing: 0.04em;
  padding: 12px 24px;
  border: none;
  text-decoration: none;
  transition: background 0.2s, transform 0.15s;
  white-space: nowrap;
}
.btn-primary:hover { background: #012A2D; }
.btn-primary.btn-accent { background: #7ECBAF; color: #003F2D; }
.btn-primary.btn-accent:hover { background: #9DDBC0; }
.btn-sm { padding: 8px 18px; font-size: 0.8rem; }

.btn-ghost-dark {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1.5px solid #003F2D;
  color: #003F2D;
  font-weight: 600;
  font-size: 0.875rem;
  padding: 10px 22px;
  text-decoration: none;
  transition: background 0.2s, color 0.2s;
}
.btn-ghost-dark:hover { background: #003F2D; color: #fff; }

.btn-outline-light {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1px solid rgba(255,255,255,0.4);
  color: #fff;
  font-size: 0.875rem;
  font-weight: 600;
  padding: 11px 22px;
  text-decoration: none;
  transition: background 0.2s, border-color 0.2s;
}
.btn-outline-light:hover { background: rgba(255,255,255,0.1); border-color: rgba(255,255,255,0.65); }

/* ── Site Header ── */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(0,0,0,0);
  transition: background 0.3s, box-shadow 0.3s;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.site-header.scrolled {
  background: rgba(1,42,45,0.97);
  backdrop-filter: blur(12px);
  box-shadow: 0 2px 20px rgba(0,0,0,0.2);
}
.header-inner {
  display: flex;
  align-items: center;
  height: 72px;
  gap: 40px;
}

/* ── Logo ── */
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
}
.logo-mark {
  width: 36px;
  height: 36px;
  background: #7ECBAF;
  color: #003F2D;
  font-weight: 800;
  font-size: 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  letter-spacing: 0.05em;
}
.logo-text {
  font-weight: 700;
  font-size: 1.05rem;
  color: #fff;
  letter-spacing: -0.01em;
}
.logo-light .logo-text { color: #fff; }

/* ── Main Nav ── */
.main-nav { flex: 1; }
.nav-list {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
}
.nav-link {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 12px;
  font-size: 0.875rem;
  font-weight: 500;
  color: rgba(255,255,255,0.85);
  text-decoration: none;
  background: none;
  border: none;
  transition: color 0.2s;
  white-space: nowrap;
}
.nav-link:hover, .nav-link[aria-expanded="true"] { color: #fff; }
.nav-link i { font-size: 16px; transition: transform 0.2s; }
.nav-link[aria-expanded="true"] i { transform: rotate(180deg); }

/* ── Mega Menu ── */
.mega-menu {
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  background: #fff;
  border-top: 2px solid #7ECBAF;
  box-shadow: 0 20px 60px rgba(0,0,0,0.15);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: opacity 0.25s, transform 0.25s, visibility 0.25s;
  z-index: 999;
}
.mega-menu.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.mega-inner {
  display: grid;
  grid-template-columns: 1fr 1fr 340px;
  gap: 0;
  padding-top: 40px;
  padding-bottom: 40px;
}
.mega-col {
  padding: 0 40px;
  border-right: 1px solid #e5e7eb;
}
.mega-col:first-child { padding-left: 0; }
.mega-col:last-child { border-right: none; }
.mega-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #9ca3af;
  margin-bottom: 16px;
}
.mega-col ul { list-style: none; }
.mega-col ul li { margin-bottom: 4px; }
.mega-col ul li a {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 12px;
  font-size: 0.9rem;
  font-weight: 500;
  color: #374151;
  text-decoration: none;
  border-radius: 4px;
  transition: background 0.15s, color 0.15s;
}
.mega-col ul li a i { font-size: 16px; color: #003F2D; }
.mega-col ul li a:hover { background: #f3f4f6; color: #003F2D; }

.mega-featured { padding-right: 0; }
.mega-feature-card {
  border: 1px solid #e5e7eb;
  overflow: hidden;
}
.mega-feature-img {
  height: 140px;
  background: linear-gradient(135deg, #003F2D, #012A2D);
  background-image: url('https://images.unsplash.com/photo-1486325212027-8081e485255e?w=400&q=60');
  background-size: cover;
  background-position: center;
  opacity: 0.85;
}
.mega-feature-body { padding: 16px; }
.mega-feature-tag {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #003F2D;
  background: rgba(0,63,45,0.08);
  padding: 2px 6px;
  display: inline-block;
  margin-bottom: 8px;
}
.mega-feature-body p { font-size: 0.875rem; font-weight: 600; color: #111827; line-height: 1.4; margin-bottom: 12px; }
.mega-feature-link { font-size: 12px; font-weight: 600; color: #003F2D; display: flex; align-items: center; gap: 6px; }
.mega-feature-link:hover { gap: 10px; }

/* ── Mobile Menu Button ── */
.mobile-menu-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  padding: 4px;
  cursor: pointer;
}
.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 2px;
  background: #fff;
  transition: transform 0.3s, opacity 0.3s;
}
.mobile-menu-btn.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.mobile-menu-btn.open span:nth-child(2) { opacity: 0; }
.mobile-menu-btn.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* ── Mobile Nav ── */
.mobile-nav {
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: #012A2D;
  z-index: 998;
  overflow-y: auto;
  opacity: 0;
  visibility: hidden;
  transform: translateX(-100%);
  transition: opacity 0.3s, visibility 0.3s, transform 0.3s;
}
.mobile-nav.open {
  opacity: 1;
  visibility: visible;
  transform: translateX(0);
}
.mobile-nav-inner { padding: 24px 24px 40px; }
.mobile-nav-inner ul { list-style: none; }
.mobile-nav-inner ul li {
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.mobile-nav-inner ul li > a,
.mobile-acc-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 16px 0;
  color: rgba(255,255,255,0.85);
  font-size: 0.95rem;
  font-weight: 500;
  background: none;
  border: none;
  text-align: left;
  font-family: 'Inter', sans-serif;
  transition: color 0.2s;
}
.mobile-acc-trigger:hover, .mobile-nav-inner ul li > a:hover { color: #7ECBAF; }
.mobile-acc-trigger i { transition: transform 0.25s; }
.mobile-acc-trigger.open i { transform: rotate(180deg); }
.mobile-acc-content {
  display: none;
  padding-bottom: 12px;
  padding-left: 12px;
}
.mobile-acc-content.open { display: block; }
.mobile-acc-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #7ECBAF;
  margin: 12px 0 8px;
}
.mobile-acc-content a {
  display: block;
  padding: 8px 0;
  color: rgba(255,255,255,0.65);
  font-size: 0.875rem;
  text-decoration: none;
  transition: color 0.2s;
}
.mobile-acc-content a:hover { color: #fff; }

/* ── Page Hero (interior pages) ── */
.page-hero {
  padding: 140px 0 80px;
  background: linear-gradient(135deg, #003F2D 0%, #012A2D 100%);
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px);
  background-size: 60px 60px;
}
.page-hero-content { position: relative; z-index: 1; max-width: 760px; }
.page-hero .breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 20px;
  font-size: 13px;
  color: rgba(255,255,255,0.5);
}
.page-hero .breadcrumb a { color: rgba(255,255,255,0.55); text-decoration: none; }
.page-hero .breadcrumb a:hover { color: #7ECBAF; }
.page-hero .breadcrumb i { font-size: 14px; }
.page-hero h1 {
  font-family: 'Playfair Display', serif;
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 600;
  color: #fff;
  line-height: 1.15;
  margin-bottom: 20px;
}
.page-hero p {
  color: rgba(255,255,255,0.7);
  font-size: 1.1rem;
  line-height: 1.75;
  max-width: 600px;
}

/* ── Section padding ── */
.section-pad { padding: 80px 0; }
.section-pad-lg { padding: 100px 0; }

/* ── Cards / Grids ── */
.cap-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: #e5e7eb;
  border: 1px solid #e5e7eb;
  margin-top: 48px;
}
.cap-card {
  background: #fff;
  padding: 36px 32px;
  transition: background 0.2s;
}
.cap-card:hover { background: #f8f9fa; }
.cap-card .cap-icon {
  width: 48px;
  height: 48px;
  background: rgba(0,63,45,0.07);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #003F2D;
  font-size: 22px;
  margin-bottom: 20px;
}
.cap-card h3 { font-size: 1rem; font-weight: 700; color: #111827; margin-bottom: 10px; }
.cap-card p { font-size: 0.875rem; color: #6b7280; line-height: 1.7; margin-bottom: 16px; }
.cap-card a { font-size: 13px; font-weight: 600; color: #003F2D; display: inline-flex; align-items: center; gap: 6px; }
.cap-card a:hover { gap: 10px; }

/* ── Related Insights ── */
.related-insights { padding: 80px 0; background: #f8f9fa; }
.related-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 36px;
}
.ri-card {
  background: #fff;
  border: 1px solid #e5e7eb;
  padding: 28px;
  transition: box-shadow 0.2s;
}
.ri-card:hover { box-shadow: 0 8px 30px rgba(0,0,0,0.07); }
.ri-card .tag { font-size: 10px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: #003F2D; margin-bottom: 10px; }
.ri-card h4 { font-size: 0.95rem; font-weight: 600; color: #111827; line-height: 1.5; margin-bottom: 12px; }
.ri-card .date { font-size: 12px; color: #9ca3af; }

/* ── Site Footer ── */
.site-footer {
  background: #012A2D;
  padding: 64px 0 0;
}
.footer-top {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 80px;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.footer-brand .logo { margin-bottom: 16px; }
.footer-brand p {
  color: rgba(255,255,255,0.5);
  font-size: 0.875rem;
  line-height: 1.7;
  margin-bottom: 20px;
}
.social-links { display: flex; gap: 12px; }
.social-links a {
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255,255,255,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.55);
  font-size: 16px;
  transition: border-color 0.2s, color 0.2s;
}
.social-links a:hover { border-color: #7ECBAF; color: #7ECBAF; }
.footer-cols {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 40px;
}
.footer-col-title {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.35);
  margin-bottom: 16px;
}
.footer-cols a {
  display: block;
  padding: 5px 0;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  text-decoration: none;
  transition: color 0.2s;
}
.footer-cols a:hover { color: #7ECBAF; }
.footer-bottom {
  padding: 24px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}
