/* ── Page Hero (interior pages) ── */
.page-hero {
  padding: 140px 0 80px;
  background: linear-gradient(135deg, #003F2D 0%, #012A2D 100%);
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px);
  background-size: 60px 60px;
}
.page-hero-content { position: relative; z-index: 1; max-width: 760px; }
.page-hero .breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 20px;
  font-size: 13px;
  color: rgba(255,255,255,0.5);
}
.page-hero .breadcrumb a { color: rgba(255,255,255,0.55); text-decoration: none; }
.page-hero .breadcrumb a:hover { color: #7ECBAF; }
.page-hero .breadcrumb i { font-size: 14px; }
.page-hero h1 {
  font-family: 'Playfair Display', serif;
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 600;
  color: #fff;
  line-height: 1.15;
