}

/* ── Section padding ── */
.section-pad { padding: 80px 0; }
.section-pad-lg { padding: 100px 0; }

/* ── Cards / Grids ── */
.cap-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: #e5e7eb;
  border: 1px solid #e5e7eb;
  margin-top: 48px;
}
.cap-card {
  background: #fff;
  padding: 36px 32px;
  transition: background 0.2s;
}
.cap-card:hover { background: #f8f9fa; }
.cap-card .cap-icon {
  width: 48px;
  height: 48px;
  background: rgba(0,63,45,0.07);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #003F2D;
  font-size: 22px;
  margin-bottom: 20px;
}
.cap-card h3 { font-size: 1rem; font-weight: 700; color: #111827; margin-bottom: 10px; }
.cap-card p { font-size: 0.875rem; color: #6b7280; line-height: 1.7; margin-bottom: 16px; }
.cap-card a { font-size: 13px; font-weight: 600; color: #003F2D; display: inline-flex; align-items: center; gap: 6px; }
.cap-card a:hover { gap: 10px; }

/* ── Related Insights ── */
.related-insights { padding: 80px 0; background: #f8f9fa; }
.related-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 36px;
}
.ri-card {
  background: #fff;
  border: 1px solid #e5e7eb;
  padding: 28px;
  transition: box-shadow 0.2s;
}
.ri-card:hover { box-shadow: 0 8px 30px rgba(0,0,0,0.07); }
.ri-card .tag { font-size: 10px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: #003F2D; margin-bottom: 10px; }
.ri-card h4 { font-size: 0.95rem; font-weight: 600; color: #111827; line-height: 1.5; margin-bottom: 12px; }
.ri-card .date { font-size: 12px; color: #9ca3af; }

/* ── Site Footer ── */
.site-footer {
  background: #012A2D;
  padding: 64px 0 0;
}
.footer-top {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 80px;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.footer-brand .logo { margin-bottom: 16px; }
.footer-brand p {
  color: rgba(255,255,255,0.5);
  font-size: 0.875rem;
  line-height: 1.7;
  margin-bottom: 20px;
}
.social-links { display: flex; gap: 12px; }
.social-links a {
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255,255,255,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.55);
  font-size: 16px;
  transition: border-color 0.2s, color 0.2s;
}
.social-links a:hover { border-color: #7ECBAF; color: #7ECBAF; }
.footer-cols {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 40px;
}
.footer-col-title {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.35);
  margin-bottom: 16px;
}
.footer-cols a {
  display: block;
  padding: 5px 0;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  text-decoration: none;
  transition: color 0.2s;
}
.footer-cols a:hover { color: #7ECBAF; }
.footer-bottom {
  padding: 24px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}
.footer-bottom p { font-size: 13px; color: rgba(255,255,255,0.35); }
.footer-legal { display: flex; gap: 24px; flex-wrap: wrap; }
.footer-legal a { font-size: 12px; color: rgba(255,255,255,0.35); text-decoration: none; transition: color 0.2s; }
.footer-legal a:hover { color: rgba(255,255,255,0.65); }

/* ── Dividers ── */
.divider { width: 48px; height: 3px; background: #7ECBAF; margin: 20px 0; }

/* ── Responsive ── */
@media (max-width: 1024px) {
  .main-nav { display: none; }
  .mobile-menu-btn { display: flex; }
  .header-actions .btn-primary { display: none; }
  .footer-top { grid-template-columns: 1fr; gap: 40px; }
  .footer-cols { grid-template-columns: repeat(2, 1fr); }
  .cap-grid { grid-template-columns: repeat(2, 1fr); }
  .related-insights-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 640px) {
  .footer-cols { grid-template-columns: 1fr 1fr; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
  .cap-grid { grid-template-columns: 1fr; }
  .related-insights-grid { grid-template-columns: 1fr; }
}

/* ── Reset & Base ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 16px;
  color: #111827;
  background: #fff;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { cursor: pointer; font-family: inherit; }

/* ── Variables ── */
:root {
  --green: #003F2D;
  --teal: #012A2D;
  --accent: #7ECBAF;
  --gray-50: #f8f9fa;
  --gray-100: #f3f4f6;
  --gray-200: #e5e7eb;
  --gray-400: #9ca3af;
  --gray-600: #4b5563;
  --gray-700: #374151;
  --gray-900: #111827;
  --container-pad: clamp(20px, 5vw, 80px);
  --container-max: 1280px;
}

/* ── Layout ── */
.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--container-pad);
}

/* ── Typography ── */
.section-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #003F2D;
  margin-bottom: 12px;
}
.section-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  font-weight: 600;
  color: #111827;
  line-height: 1.25;
}

/* ── Buttons ── */
.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #003F2D;
  color: #fff;
  font-weight: 600;
  font-size: 0.875rem;
  letter-spacing: 0.04em;
  padding: 12px 24px;
  border: none;
  text-decoration: none;
  transition: background 0.2s, transform 0.15s;
  white-space: nowrap;
}
.btn-primary:hover { background: #012A2D; }
.btn-primary.btn-accent { background: #7ECBAF; color: #003F2D; }
.btn-primary.btn-accent:hover { background: #9DDBC0; }
.btn-sm { padding: 8px 18px; font-size: 0.8rem; }

.btn-ghost-dark {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1.5px solid #003F2D;
  color: #003F2D;
  font-weight: 600;
  font-size: 0.875rem;
  padding: 10px 22px;
  text-decoration: none;
  transition: background 0.2s, color 0.2s;
}
.btn-ghost-dark:hover { background: #003F2D; color: #fff; }

.btn-outline-light {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1px solid rgba(255,255,255,0.4);
  color: #fff;
  font-size: 0.875rem;
  font-weight: 600;
  padding: 11px 22px;
  text-decoration: none;
  transition: background 0.2s, border-color 0.2s;
}
.btn-outline-light:hover { background: rgba(255,255,255,0.1); border-color: rgba(255,255,255,0.65); }

/* ── Site Header ── */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(0,0,0,0);
  transition: background 0.3s, box-shadow 0.3s;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
