/* ── Reset & Base ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 16px;
  color: #111827;
  background: #fff;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { cursor: pointer; font-family: inherit; }

/* ── Variables ── */
:root {
  --green: #003F2D;
  --teal: #012A2D;
  --accent: #7ECBAF;
  --gray-50: #f8f9fa;
  --gray-100: #f3f4f6;
  --gray-200: #e5e7eb;
  --gray-400: #9ca3af;
  --gray-600: #4b5563;
  --gray-700: #374151;
  --gray-900: #111827;
  --container-pad: clamp(20px, 5vw, 80px);
  --container-max: 1280px;
}

/* ── Layout ── */
.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--container-pad);
}

/* ── Typography ── */
.section-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #003F2D;
  margin-bottom: 12px;
}
.section-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  font-weight: 600;
  color: #111827;
  line-height: 1.25;
}

/* ── Buttons ── */
.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #003F2D;
  color: #fff;
  font-weight: 600;
  font-size: 0.875rem;
  letter-spacing: 0.04em;
  padding: 12px 24px;
  border: none;
  text-decoration: none;
  transition: background 0.2s, transform 0.15s;
  white-space: nowrap;
}
.btn-primary:hover { background: #012A2D; }
.btn-primary.btn-accent { background: #7ECBAF; color: #003F2D; }
.btn-primary.btn-accent:hover { background: #9DDBC0; }
.btn-sm { padding: 8px 18px; font-size: 0.8rem; }

.btn-ghost-dark {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1.5px solid #003F2D;
  color: #003F2D;
  font-weight: 600;
  font-size: 0.875rem;
  padding: 10px 22px;
  text-decoration: none;
  transition: background 0.2s, color 0.2s;
}
.btn-ghost-dark:hover { background: #003F2D; color: #fff; }

.btn-outline-light {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1px solid rgba(255,255,255,0.4);
  color: #fff;
  font-size: 0.875rem;
  font-weight: 600;
  padding: 11px 22px;
  text-decoration: none;
  transition: background 0.2s, border-color 0.2s;
}
.btn-outline-light:hover { background: rgba(255,255,255,0.1); border-color: rgba(255,255,255,0.65); }

/* ── Site Header ── */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(0,0,0,0);
  transition: background 0.3s, box-shadow 0.3s;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
