  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Design &amp; Build — GlobalStone</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Playfair+Display:wght@500;600;700&display=swap" rel="stylesheet" />
  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/remixicon/4.2.0/remixicon.min.css" />
  <link rel="stylesheet" href="shared.css" />
  <style>
    /* ── Intro ── */
    .intro-band {
      padding: 80px 0;
      background: #fff;
      border-bottom: 1px solid #e5e7eb;
    }
    .intro-band-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .intro-band h2 {
      font-family: 'Playfair Display', serif;
      font-size: clamp(1.7rem, 2.8vw, 2.3rem);
      font-weight: 600;
      color: #111827;
      line-height: 1.3;
    }
    .intro-band p { color: #4b5563; font-size: 1.05rem; line-height: 1.85; }
    .intro-band ul {
      list-style: none;
      margin-top: 24px;
    }
    .intro-band ul li {
      display: flex;
      align-items: flex-start;
      gap: 10px;
      padding: 8px 0;
      font-size: 0.9rem;
      color: #374151;
      border-bottom: 1px solid #f3f4f6;
    }
    .intro-band ul li:last-child { border-bottom: none; }
    .intro-band ul li i { color: #003F2D; font-size: 16px; flex-shrink: 0; margin-top: 2px; }

    /* ── Process Steps ── */
    .process-section { padding: 80px 0; background: #f8f9fa; }
    .process-steps {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 0;
      margin-top: 48px;
      border: 1px solid #e5e7eb;
    }
    .process-step {
      padding: 36px 28px;
      border-right: 1px solid #e5e7eb;
      position: relative;
      background: #fff;
      transition: background 0.2s;
    }
    .process-step:last-child { border-right: none; }
    .process-step:hover { background: #f8f9fa; }
    .step-num {
      font-family: 'Playfair Display', serif;
      font-size: 3rem;
      font-weight: 700;
      color: rgba(0,63,45,0.08);
      line-height: 1;
      margin-bottom: 16px;
    }
    .process-step h4 { font-size: 1rem; font-weight: 700; color: #111827; margin-bottom: 10px; }
    .process-step p { font-size: 0.875rem; color: #6b7280; line-height: 1.7; }

    /* ── Capabilities (Design & Build — 2 cards) ── */
    .capabilities-section { padding: 80px 0; background: #fff; }
    .db-cap-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 32px;
      margin-top: 48px;
    }
    .db-cap-card {
      border: 1px solid #e5e7eb;
      overflow: hidden;
      transition: box-shadow 0.25s;
    }
    .db-cap-card:hover { box-shadow: 0 16px 48px rgba(0,0,0,0.08); }
    .db-cap-img {
      height: 220px;
      background: linear-gradient(135deg, #003F2D, #012A2D);
      position: relative;
      overflow: hidden;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .db-cap-img img { width: 100%; height: 100%; object-fit: cover; opacity: 0.5; }
    .db-cap-img .cap-icon-overlay {
      position: absolute;
      font-size: 52px;
      color: rgba(126,203,175,0.8);
    }
    .db-cap-body { padding: 36px; }
    .db-cap-body .tag {
      font-size: 10px;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: #003F2D;
      margin-bottom: 10px;
    }
    .db-cap-body h3 { font-size: 1.2rem; font-weight: 700; color: #111827; margin-bottom: 12px; }
    .db-cap-body p { font-size: 0.9rem; color: #6b7280; line-height: 1.75; margin-bottom: 24px; }
    .db-cap-body ul {
      list-style: none;
      margin-bottom: 24px;
    }
    .db-cap-body ul li {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 0.875rem;
      color: #374151;
      padding: 6px 0;
      border-bottom: 1px solid #f3f4f6;
    }
    .db-cap-body ul li:last-child { border-bottom: none; }
    .db-cap-body ul li i { color: #003F2D; font-size: 14px; }

    /* ── Partnership Highlight ── */
    .partnership-section { padding: 80px 0; background: #012A2D; }
    .partnership-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .partnership-section .section-label { color: rgba(255,255,255,0.5); }
    .partnership-section h2 {
      font-family: 'Playfair Display', serif;
      font-size: clamp(1.7rem, 2.8vw, 2.3rem);
      font-weight: 600;
      color: #fff;
      line-height: 1.3;
      margin-top: 8px;
    }
    .partnership-section p {
      color: rgba(255,255,255,0.65);
      font-size: 1.05rem;
      line-height: 1.85;
      margin-top: 20px;
    }
    .partnership-metrics {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 20px;
      margin-top: 32px;
    }
    .p-metric {
      padding: 24px;
      border: 1px solid rgba(255,255,255,0.1);
      background: rgba(255,255,255,0.03);
    }
    .p-metric .val {
      font-family: 'Playfair Display', serif;
      font-size: 2rem;
      font-weight: 700;
      color: #7ECBAF;
      margin-bottom: 6px;
    }
    .p-metric .desc { font-size: 0.85rem; color: rgba(255,255,255,0.55); line-height: 1.5; }
    .partner-logos {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 16px;
    }
    .partner-logo-placeholder {
      height: 80px;
      border: 1px solid rgba(255,255,255,0.1);
      background: rgba(255,255,255,0.03);
      display: flex;
      align-items: center;
      justify-content: center;
      color: rgba(255,255,255,0.3);
      font-size: 12px;
      font-weight: 600;
      letter-spacing: 0.06em;
      text-transform: uppercase;
    }

    /* ── CTA Section ── */
    .db-cta { padding: 80px 0; background: #003F2D; }
    .db-cta-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .db-cta h2 {
      font-family: 'Playfair Display', serif;
      font-size: 2.2rem;
      color: #fff;
      margin-bottom: 16px;
    }
    .db-cta p { color: rgba(255,255,255,0.65); font-size: 1.05rem; line-height: 1.75; margin-bottom: 32px; }
    .contact-form {
      display: flex;
      flex-direction: column;
      gap: 14px;
    }
    .form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
    .contact-form input,
    .contact-form select,
    .contact-form textarea {
      padding: 13px 16px;
      background: rgba(255,255,255,0.07);
      border: 1px solid rgba(255,255,255,0.18);
      color: #fff;
      font-size: 0.9rem;
      font-family: 'Inter', sans-serif;
      outline: none;
      transition: border-color 0.2s;
    }
    .contact-form input::placeholder,
    .contact-form textarea::placeholder { color: rgba(255,255,255,0.4); }
    .contact-form input:focus,
    .contact-form select:focus,
    .contact-form textarea:focus { border-color: #7ECBAF; }
    .contact-form select option { background: #012A2D; color: #fff; }
    .contact-form textarea { resize: vertical; min-height: 100px; }
    .contact-form button {
      background: #7ECBAF;
      color: #003F2D;
      font-weight: 700;
      font-size: 0.875rem;
      padding: 14px 28px;
      border: none;
      cursor: pointer;
      font-family: 'Inter', sans-serif;
      align-self: flex-start;
      letter-spacing: 0.04em;
      transition: background 0.2s;
    }
    .contact-form button:hover { background: #9DDBC0; }

    @media (max-width: 1024px) {
      .intro-band-inner,
      .partnership-inner,
      .db-cta-inner { grid-template-columns: 1fr; gap: 40px; }
      .process-steps { grid-template-columns: repeat(2, 1fr); }
      .process-step:nth-child(2) { border-right: none; }
      .process-step:nth-child(3) { border-right: 1px solid #e5e7eb; border-top: 1px solid #e5e7eb; }
      .process-step:nth-child(4) { border-top: 1px solid #e5e7eb; border-right: none; }
      .db-cap-grid { grid-template-columns: 1fr; }
    }
    @media (max-width: 640px) {
      .process-steps { grid-template-columns: 1fr; }
      .process-step { border-right: none; border-bottom: 1px solid #e5e7eb; }
      .process-step:last-child { border-bottom: none; }
      .form-row { grid-template-columns: 1fr; }
      .partnership-metrics { grid-template-columns: 1fr; }
    }
  </style>
</head>
