  <!-- INTRO STATEMENT -->
  <section class="intro-band">
    <div class="container intro-band-inner">
      <div>
        <div class="section-label">Our Approach</div>
        <h2>Turnkey delivery from concept through occupancy.</h2>
        <p style="margin-top:16px; color:#6b7280; font-size:0.95rem; line-height:1.8;">Our integrated approach encompasses every phase of the real estate development and delivery lifecycle — ensuring seamless coordination between all stakeholders from day one.</p>
      </div>
      <div>
        <p>Whether you're building a corporate headquarters, a logistics facility, or a mixed-use development, GlobalStone's Design &amp; Build team brings deep expertise in project delivery, supply chain optimization, and stakeholder management. We are the single accountable partner that takes your project from strategy to keys in hand.</p>
        <ul>
          <li><i class="ri-check-line"></i> End-to-end project accountability</li>
          <li><i class="ri-check-line"></i> Integrated design and construction coordination</li>
          <li><i class="ri-check-line"></i> Proprietary cost benchmarking and risk management</li>
          <li><i class="ri-check-line"></i> Global delivery network, local expertise</li>
          <li><i class="ri-check-line"></i> Sustainability-first design philosophy</li>
        </ul>
        <div style="margin-top:28px;">
          <a href="#" class="btn-primary">Start Your Project <i class="ri-arrow-right-line"></i></a>
        </div>
      </div>
    </div>
  </section>

  <!-- PROCESS STEPS -->
  <section class="process-section">
    <div class="container">
      <div class="section-label">Our Process</div>
      <h2 class="section-title" style="margin-top:8px;">From Vision to Reality</h2>
      <div class="process-steps">
        <div class="process-step">
          <div class="step-num">01</div>
          <h4>Strategy &amp; Feasibility</h4>
          <p>We assess your business strategy, program requirements, and financial objectives to develop a clear project brief and feasibility framework.</p>
        </div>
        <div class="process-step">
          <div class="step-num">02</div>
          <h4>Design &amp; Planning</h4>
          <p>Coordinating architecture, engineering, and interiors to create designs that balance aesthetic ambition with practical deliverability.</p>
        </div>
        <div class="process-step">
          <div class="step-num">03</div>
          <h4>Procurement &amp; Construction</h4>
          <p>Strategic sourcing, contractor selection, and construction management to deliver on cost, schedule, and quality commitments.</p>
        </div>
        <div class="process-step">
          <div class="step-num">04</div>
          <h4>Handover &amp; Closeout</h4>
          <p>Rigorous commissioning, testing, and handover protocols ensure your space is ready for occupancy from day one.</p>
        </div>
      </div>
    </div>
  </section>

  <!-- CAPABILITIES -->
  <section class="capabilities-section">
    <div class="container">
      <div class="section-label">Capabilities</div>
      <h2 class="section-title" style="margin-top:8px;">Core Service Areas</h2>
      <div class="db-cap-grid">
        <div class="db-cap-card">
